import{_ as n,o as e,c as l,a2 as s,j as t,a}from"./chunks/framework.DxqK4cCD.js";const E=JSON.parse('{"title":"Adaptive Tokenisation Via Temporal Redundancy Masking And Latent Inpainting","description":"提出一种参数无关的自适应视频令牌分配方法，利用潜在空间时间冗余性实现高效压缩和修复。","frontmatter":{"title":"Adaptive Tokenisation Via Temporal Redundancy Masking And Latent Inpainting","description":"提出一种参数无关的自适应视频令牌分配方法，利用潜在空间时间冗余性实现高效压缩和修复。","date":"2026-06-07","arxivId":"2606.06158","domain":"计算机视觉","level":"进阶","tags":["自适应令牌化","时间冗余掩码","潜在修复","视频压缩","高效推理"],"originalUrl":"https://arxiv.org/abs/2606.06158","sourceUrl":"https://github.com/vsvnakers/paper-daily/blob/master/essay_read/2026-06-07/2606.06158.md"},"headers":[],"relativePath":"papers/daily/2026-06-07/2606.06158.md","filePath":"papers/daily/2026-06-07/2606.06158.md","lastUpdated":1786541753000}'),r={name:"papers/daily/2026-06-07/2606.06158.md"};function o(p,i,h,d,g,k){return e(),l("div",null,[...i[0]||(i[0]=[s("",15),t("ul",null,[t("li",null,[t("strong",null,"核心机制：时间冗余掩码（Temporal Redundancy Masking）"),a("：给定一个冻结的连续视频令牌化器（如C-ViViT），输入视频帧序列 ${x_1, x_2, ..., x_T}$，首先通过编码器得到潜在表示序列 ${z_1, z_2, ..., z_T}$，其中 $z_t \\in \\mathbb{R}^{H \\times W \\times D}$，$H$ 和 $W$ 是空间维度，$D$ 是通道维度。对于第 $t$ 帧的每个空间位置 $(i, j)$，计算其与前一帧对应位置的时间L1差异：$\\Delta_{t}(i,j) = ||z_t(i,j) - z_{t-1}(i,j)||"),t("em",{t:""},"1$。然后，应用一个固定的阈值 $\\tau$ 来生成掩码 $M_t$：如果 $\\Delta"),a("(i,j) < \\tau$，则 $M_t(i,j) = 0$（表示该位置冗余，将被丢弃）；否则 $M_t(i,j) = 1$（表示该位置重要，将被保留）。")]),t("li",null,[t("strong",null,"参数无关性与内容驱动压缩"),a("：该机制没有任何可学习参数，阈值 $\\tau$ 是一个超参数，但论文通过实验证明其在不同数据集上表现鲁棒。压缩率完全由输入视频的动态性决定：静态场景中 $\\Delta_t$ 普遍较小，导致大量位置被丢弃，压缩率高；动态场景中 $\\Delta_t$ 较大，保留更多令牌，压缩率低。这实现了真正的“内容驱动”压缩。")]),t("li",null,[t("strong",null,"潜在修复变换器（LIT）架构"),a("：LIT是一个轻量级的变换器，用于重建被丢弃的潜在位置。其核心是分解式时空注意力（Factorised Spatial-Temporal Attention）。首先，将保留的潜在位置和丢弃的位置（用可学习的掩码令牌[MASK]填充）组成一个完整的潜在张量。然后，LIT依次执行：1）空间注意力（Spatial Attention）：在每个时间步内，让每个空间位置关注同一帧内的其他空间位置，利用保留的令牌信息修复当前帧内的丢弃位置。2）时间注意力（Temporal Attention）：在每个空间位置上，让该位置关注不同时间步的对应位置，利用时间上下文信息进一步修复。这种分解设计大幅降低了计算复杂度，相比全局时空注意力（Global Spatio-Temporal Attention）更加高效。")]),t("li",null,[t("strong",null,"推理流程"),a("：1）输入视频帧序列，通过冻结的编码器得到潜在表示。2）计算时间L1差异并生成掩码，丢弃冗余潜在位置。3）将保留的潜在位置和[MASK]令牌组合成不完整的潜在张量。4）将不完整的潜在张量输入LIT，LIT通过分解式时空注意力修复被丢弃的位置。5）将修复后的完整潜在张量输入冻结的解码器，重建视频帧。")]),t("li",null,[t("strong",null,"与现有方法的本质区别"),a("：现有方法（如ElasticTok）需要训练一个额外的路由网络（Routing Network）来预测每个位置的令牌重要性，或者通过迭代搜索来优化分配。而论文的方法直接利用冻结编码器的潜在空间特性，无需任何额外训练或搜索，是一种“零成本”的自适应机制。LIT虽然需要训练，但其结构轻量，且只用于修复，不参与令牌分配决策。")])],-1),s("",48)])])}const u=n(r,[["render",o]]);export{E as __pageData,u as default};
